<script setup lang="ts">import{ref,computed,watch}from'vue';import type{QuestionItem}from'../types/agentChat';const p=defineProps<{id:string;questions:QuestionItem[];state?:'answered'|'skipped'}>();const s=ref<Record<string,string>>({});const ci=ref<Record<string,string>>({});const sb=ref(p.state==='answered');const sk=ref(p.state==='skipped');const aa=computed(()=>p.questions.every(q=>s.value[q.prompt]||(ci.value[q.prompt]||'').trim()));// 父级回写 state（gateway markQuestionState）时同步本地视图，防跨分支重建/复用后卡片"复活"可交互
watch(()=>p.state,v=>{if(v==='answered'){sb.value=true;sk.value=false}else if(v==='skipped'){sk.value=true;sb.value=false}});function hs(q:string,l:string){s.value={...s.value,[q]:l};ci.value={...ci.value,[q]:''}};function hc(q:string,v:string){ci.value={...ci.value,[q]:v};s.value={...s.value,[q]:''}};function hm(){if(!aa.value)return;sb.value=true;const a:Record<string,string>={};for(const q of p.questions){if(ci.value[q.prompt]?.trim())a[q.prompt]=`[custom] ${ci.value[q.prompt]}`;else a[q.prompt]=s.value[q.prompt]||''};window.dispatchEvent(new CustomEvent('ask-question-submit',{detail:{id:p.id,answers:a}}))};function hk(){sk.value=true;window.dispatchEvent(new CustomEvent('ask-question-skip',{detail:{id:p.id}}))}</script>
<template><div v-if="sb" class="aqc aqc-submitted"><div class="aqc-hdr"><span class="aqc-icon">?</span><span class="aqc-title">Question</span><span class="aqc-badge badge-answered">answered</span></div><div class="aqc-body"><p style="font-size:12px;color:var(--text-body);opacity:.7">Your answers have been submitted.</p></div></div>
<div v-else-if="sk" class="aqc aqc-submitted"><div class="aqc-hdr"><span class="aqc-icon">?</span><span class="aqc-title">Question</span><span class="aqc-badge badge-skipped">skipped</span></div><div class="aqc-body"><p style="font-size:12px;color:var(--text-body);opacity:.7">Question skipped.</p></div></div>
<div v-else class="aqc"><div class="aqc-hdr"><span class="aqc-icon">?</span><span class="aqc-title">Agent Question</span><span class="aqc-badge">awaiting</span></div><div class="aqc-body"><div v-for="(q,qi) in questions" :key="qi" class="aqc-q"><div class="aqc-q-title"><span class="aqc-chip">{{q.title}}</span><span class="aqc-qnum">{{qi+1}}/{{questions.length}}</span></div><p class="aqc-qtext">{{q.prompt}}</p><div class="aqc-options"><button v-for="(opt,oi) in q.options" :key="oi" class="aqc-opt" :class="{selected:s[q.prompt]===opt.label}" :disabled="(ci[q.prompt]||'').trim().length>0" @click="hs(q.prompt,opt.label)"><span class="aqc-opt-label">{{opt.label}}</span><span class="aqc-opt-desc">{{opt.detail}}</span></button></div><div class="aqc-custom"><div class="aqc-custom-hdr"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="color:var(--accent)"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg><span>custom answer</span></div><input class="aqc-input" type="text" placeholder="type your own answer..." :value="ci[q.prompt]||''" @input="hc(q.prompt,($event.target as HTMLInputElement).value)"/></div></div></div><div class="aqc-actions"><button class="aqc-skip" @click="hk">skip</button><button class="aqc-submit" :disabled="!aa" @click="hm">submit answers</button></div></div></template>
